  ["stats.confirmUnsubscribe", "\u786E\u8BA4\u9000\u8BA2\uFF1F", "Confirm unsubscribe?", "\u78BA\u8A8D\u9000\u8A02\uFF1F", "\u8CFC\u8AAD\u89E3\u9664\u3057\u307E\u3059\u304B\uFF1F", "\uAD6C\uB3C5 \uD574\uC9C0\uD560\uAE4C\uC694?", "\xBFConfirmar baja?", "Confirmer la d\xE9sinscription ?", "Abbestellung best\xE4tigen?"],
  ["stats.unsubscribed", "\u5DF2\u9000\u8BA2 {name}\u3002", "Unsubscribed from {name}.", "\u5DF2\u9000\u8A02 {name}\u3002", "{name} \u306E\u8CFC\u8AAD\u3092\u89E3\u9664\u3057\u307E\u3057\u305F\u3002", "{name} \uAD6C\uB3C5\uC744 \uD574\uC9C0\uD588\uC2B5\uB2C8\uB2E4.", "Dado de baja de {name}.", "D\xE9sinscrit de {name}.", "{name} abbestellt."],
  ["stats.unsubscribeFailed", "\u9000\u8BA2\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5\u3002", "Could not unsubscribe. Please try again.", "\u9000\u8A02\u5931\u6557\uFF0C\u8ACB\u91CD\u8A66\u3002", "\u8CFC\u8AAD\u3092\u89E3\u9664\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u3082\u3046\u4E00\u5EA6\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002", "\uAD6C\uB3C5 \uD574\uC9C0\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "No se pudo darse de baja. Int\xE9ntalo de nuevo.", "\xC9chec de la d\xE9sinscription. R\xE9essayez.", "Abbestellen fehlgeschlagen. Bitte erneut versuchen."]
