// src/shared-audio/runtime/registry.js
var registry2 = { models };
var LOCAL_MODELS = Object.entries(registry2.models).filter(([, value]) => value.kind !== "asr").map(([id, value]) => ({ id, ...value }));
var ASR_MODELS = Object.entries(registry2.models).filter(([, value]) => value.kind === "asr").map(([id, value]) => ({ id, ...value }));
var LOCAL_DEFAULT_MODEL = "kokoro";
var LOCAL_DEFAULT_VOICE = registry2.models.kokoro.defaultVoice;
function normalizeLocalProfile(profile = {}) {
  const model = registry2.models[profile.model]?.kind !== "asr" && registry2.models[profile.model] ? profile.model : LOCAL_DEFAULT_MODEL;
  const voice = registry2.models[model].voices.some((v2) => v2.id === profile.voice) ? profile.voice : registry2.models[model].defaultVoice;
  return { ...profile, model, voice };
}
function localVoiceChoices(model, chinese = true) {
  return (registry2.models[model]?.voices || []).map((v2) => {
    const language2 = !chinese ? v2.lang : !v2.lang.startsWith("zh") ? "\u82F1\u6587" : v2.gender === "male" ? "\u4E2D\u6587\u7537\u58F0" : v2.gender === "female" ? "\u4E2D\u6587\u5973\u58F0" : "";
    return {
      id: v2.id,
      label: [
        chinese ? v2.name : v2.nameEn,
        language2,
        v2.recommended ? chinese ? "\u63A8\u8350" : "Recommended" : ""
      ].filter(Boolean).join(" \xB7 "),
      sourceName: `${registry2.models[model].label} \xB7 ${v2.id}`,
      recommended: !!v2.recommended
    };
  });
}

// src/shared-audio/core/tts/text.js
function splitSpeechText(text2, maxLength = 240, clauses = false) {
  const result = [];
  let start = 0;
  const pieces = typeof Intl.Segmenter === "function" ? [...new Intl.Segmenter(void 0, { granularity: "sentence" }).segment(text2)].map((x2) => x2.segment) : text2.match(/[^。！？.!?\n]+[。！？.!?\n]*|[。！？.!?\n]+/gu) || [];
  const sentences = clauses ? pieces.flatMap((piece) => piece.match(/[^，,；;]+[，,；;]*|[，,；;]+/gu) || []) : pieces;
  for (const sentence of sentences) {
    let rest = sentence;
    while (rest.length) {
      let length = Math.min(maxLength, rest.length);
      if (length < rest.length && /[\uD800-\uDBFF]/.test(rest[length - 1])) length--;
      const raw = rest.slice(0, length);
      if (raw.trim()) result.push({ text: raw.replace(/\s+/g, " ").trim(), start, end: start + length });
      start += length;
      rest = rest.slice(length);
    }
  }
  return result;
}

