  setIcon(iconEl, icon);
  const labelEl = button.createSpan({ cls: text2 ? "qaudio-button-text" : "qaudio-sr", text: label });
  button.addEventListener("click", (event) => {
    event.preventDefault();
    onClick(event);
  });
